export function findBlogPost(slug) {
  return blogPosts.find((p) => p.slug === slug);
}

export function getRelatedBlogPosts(currentSlug, limit = 3) {
  const current = findBlogPost(currentSlug);
  const category = current ? current.category : null;
  return blogPosts
    .filter((p) => p.slug !== currentSlug && (category ? p.category === category : true))
    .slice(0, limit);
}

export const blogCategories = [
  "All",
  ...Array.from(new Set(blogPosts.map((p) => p.category).filter(Boolean))),
];
